<template><div v-loading="loading"><el-tabs v-model="tab" class="workspace-tabs"><el-tab-pane label="现场挂号" name="register"><div class="two-column"><section class="card"><div class="card-heading"><h2>选择患者</h2><el-button type="primary" plain icon="el-icon-plus" @click="patientDialog=true">新增患者</el-button></div><el-input v-model="patientSearch" clearable placeholder="输入姓名或病历号" @input="searchPatients" prefix-icon="el-icon-search"/><el-table :data="patients.items" highlight-current-row @current-change="selectPatient" class="spaced-table" empty-text="暂无患者，请新增或修改查询条件"><el-table-column prop="name" label="姓名" width="100"/><el-table-column prop="gender" label="性别" width="65"/><el-table-column prop="case_no" label="病历号" min-width="170"/></el-table><el-pagination small layout="prev,pager,next" :total="patients.total" :page-size="20" :current-page.sync="patientPage" @current-change="loadPatients"/></section><section class="card"><div class="card-heading"><h2>挂号与收款</h2><span class="subtle-badge">现场挂号</span></div><div v-if="selectedPatient" class="selected-person"><b>{{selectedPatient.name}}</b><span>{{selectedPatient.gender}} · {{selectedPatient.case_no}}</span></div><el-alert v-else title="先在左侧选择患者" :closable="false" type="info"/><el-form label-position="top" class="form-grid"><el-form-item label="挂号科室"><el-select v-model="department" placeholder="选择科室" @change="scheduleId=''" clearable><el-option v-for="d in outpatientDepartments" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-form-item label="挂号级别"><el-select v-model="level" clearable placeholder="全部号别" @change="scheduleId=''"><el-option v-for="n in levels" :key="n" :label="n" :value="n"/></el-select></el-form-item><el-form-item label="当前日期"><el-input :value="today()" disabled/></el-form-item><el-form-item label="看诊医生 / 时段"><el-select v-model="scheduleId" filterable placeholder="选择排班"><el-option v-for="s in availableSchedules" :key="s.id" :value="s.id" :label="`${s.doctor_name} · ${s.period} · ${s.level_name} · 剩${s.quota-s.booked}号`"/></el-select></el-form-item><el-form-item label="病历本"><el-checkbox v-model="book">需要病历本（另收 ¥1.00）</el-checkbox></el-form-item><el-form-item label="支付方式"><el-select v-model="payMethod"><el-option v-for="p in payMethods" :key="p" :value="p"/></el-select></el-form-item><div class="amount-card full"><span>挂号应收</span><strong>{{money(registrationFee)}}</strong></div><el-form-item label="实收金额（元）"><el-input-number v-model="received" :min="0" :max="10000000" :precision="2" :controls="false"/></el-form-item><div class="form-end"><el-button type="primary" :loading="saving" @click="register">收款并完成挂号 <i class="el-icon-right"/></el-button></div></el-form></section></div></el-tab-pane>
  <el-tab-pane label="收费 / 退费 / 退号" name="billing"><section class="card"><div class="toolbar"><el-input v-model="search" clearable placeholder="输入姓名、病历号或就诊号" prefix-icon="el-icon-search" @keyup.enter.native="loadEncounters(1)"/><el-button @click="loadEncounters(1)" icon="el-icon-search">查询</el-button></div><el-table :data="encounters.items" highlight-current-row @current-change="selectEncounter"><el-table-column prop="patient_name" label="患者" width="100"/><el-table-column prop="case_no" label="病历号" min-width="170"/><el-table-column prop="doctor_name" label="医生" width="90"/><el-table-column prop="department_name" label="科室" width="100"/><el-table-column label="时间" min-width="160"><template slot-scope="s">{{date(s.row.created_at)}}</template></el-table-column><el-table-column label="状态" width="100"><template slot-scope="s"><Status :value="s.row.status"/></template></el-table-column><el-table-column label="操作" width="105"><template slot-scope="s"><el-button type="text" @click.stop="selectEncounter(s.row)">查看费用</el-button></template></el-table-column></el-table><el-pagination layout="total,prev,pager,next" :total="encounters.total" :page-size="20" :current-page.sync="page" @current-change="loadEncounters"/></section>
  <section v-if="detail" class="card section-gap"><div class="card-heading"><div><h2>{{detail.encounter.patient_name}} · 本次费用</h2><p>{{detail.encounter.visit_no}}</p></div><el-button v-if="detail.encounter.status==='REGISTERED'" type="danger" plain @click="cancelRegistration">办理退号</el-button></div><el-table ref="orders" :data="detail.orders" @selection-change="selectedOrders=$event"><el-table-column type="selection" :selectable="chargeable" width="45"/><el-table-column prop="item_name" label="项目" min-width="150"/><el-table-column label="类型" width="70"><template slot-scope="s">{{label(s.row.kind)}}</template></el-table-column><el-table-column prop="quantity" label="数量" width="65"/><el-table-column label="金额" width="100"><template slot-scope="s">{{money(s.row.amount_cents)}}</template></el-table-column><el-table-column label="费用状态" width="100"><template slot-scope="s"><Status :value="s.row.billing_status"/></template></el-table-column><el-table-column label="执行状态" width="100"><template slot-scope="s"><Status :value="s.row.execution_status" execution/></template></el-table-column><el-table-column label="操作" width="90"><template slot-scope="s"><el-button v-if="refundable(s.row)" type="text" class="danger-text" @click="refund(s.row)">退费</el-button></template></el-table-column></el-table><div class="checkout-bar"><span>选中应收 <b>{{money(selectedTotal)}}</b></span><el-select v-model="billMethod"><el-option v-for="p in payMethods" :key="p" :value="p"/></el-select><el-input-number v-model="billReceived" :controls="false" :min="0" :precision="2"/><el-button type="primary" :loading="saving" :disabled="!selectedOrders.length" @click="charge">确认收款</el-button></div><div class="card-heading"><h3>收款记录</h3></div><el-table :data="detail.invoices" empty-text="暂无记录"><el-table-column prop="receipt_no" label="收款凭证号" min-width="200"/><el-table-column label="金额"><template slot-scope="s">{{money(s.row.total_cents)}}</template></el-table-column><el-table-column prop="pay_method" label="支付方式"/><el-table-column label="收费时间" min-width="150"><template slot-scope="s">{{date(s.row.created_at)}}</template></el-table-column><el-table-column width="110"><template slot-scope="s"><el-button type="text" @click="openReceipt(s.row.id)">查看 / 打印</el-button></template></el-table-column></el-table><div v-if="detail.refunds.length"><h3>退款记录</h3><el-table :data="detail.refunds"><el-table-column prop="item_name" label="项目"/><el-table-column label="退款金额"><template slot-scope="s">{{money(s.row.amount_cents)}}</template></el-table-column><el-table-column prop="reason" label="原因"/><el-table-column label="时间"><template slot-scope="s">{{date(s.row.created_at)}}</template></el-table-column></el-table></div></section></el-tab-pane></el-tabs>
  <el-dialog title="新增患者主档" :visible.sync="patientDialog" width="650px"><el-form label-position="top" class="form-grid"><el-form-item label="姓名 *"><el-input v-model.trim="patient.name" maxlength="60"/></el-form-item><el-form-item label="性别 *"><el-select v-model="patient.gender"><el-option v-for="g in ['男','女','未知']" :key="g" :value="g"/></el-select></el-form-item><el-form-item label="出生日期"><el-date-picker v-model="patient.birth_date" type="date" value-format="yyyy-MM-dd"/></el-form-item><el-form-item label="年龄（无出生日期时可填）"><el-input-number v-model="patient.age" :min="0" :max="150"/></el-form-item><el-form-item label="结算类别 *"><el-select v-model="patient.settle_type"><el-option value="自费"/><el-option value="医保"/></el-select></el-form-item><el-form-item label="联系电话"><el-input v-model="patient.phone" maxlength="24"/></el-form-item><el-form-item label="身份证号"><el-input v-model="patient.id_card" maxlength="32"/></el-form-item><el-form-item label="家庭住址"><el-input v-model="patient.address" maxlength="200"/></el-form-item></el-form><span slot="footer"><el-button @click="patientDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="addPatient">保存患者</el-button></span></el-dialog>
  </div></template>
<script>
import {api,money,date,label,today,key,cents,reason}from'../api';import Status from'../components/Status.vue';
export default{components:{Status},props:['catalog'],data:()=>({loading:false,saving:false,tab:'register',patientSearch:'',patients:{items:[],total:0},patientPage:1,selectedPatient:null,patientDialog:false,patient:{name:'',gender:'女',birth_date:null,age:0,settle_type:'自费',id_card:'',address:'',phone:''},schedules:[],department:'',level:'',scheduleId:'',book:false,payMethod:'移动支付',received:0,payMethods:['现金','银行卡','移动支付','医保'],search:'',page:1,encounters:{items:[],total:0},detail:null,selectedOrders:[],billMethod:'移动支付',billReceived:0,searchTimer:null}),computed:{outpatientDepartments(){return this.catalog.departments.filter(d=>d.kind==='OUTPATIENT');},levels(){return[...new Set(this.schedules.map(s=>s.level_name))];},availableSchedules(){return this.schedules.filter(s=>(!this.department||s.department_id===this.department)&&(!this.level||s.level_name===this.level)&&s.booked<s.quota);},selectedSchedule(){return this.schedules.find(s=>s.id===this.scheduleId);},registrationFee(){return Number(this.selectedSchedule?.fee_cents||0)+(this.book?100:0);},selectedTotal(){return this.selectedOrders.reduce((t,o)=>t+Number(o.amount_cents),0);}},watch:{registrationFee(v){this.received=v/100;},selectedTotal(v){this.billReceived=v/100;},tab(v){if(v==='billing')this.loadEncounters();}},created(){this.loadPatients();this.loadSchedules();},beforeDestroy(){clearTimeout(this.searchTimer);},methods:{money,date,label,today,searchPatients(){clearTimeout(this.searchTimer);this.searchTimer=setTimeout(()=>{this.patientPage=1;this.loadPatients();},300);},async loadPatients(){try{this.patients=await api.get('/patients',{params:{q:this.patientSearch,page:this.patientPage}});}catch{}},async loadSchedules(){try{this.schedules=await api.get('/schedules');}catch{}},selectPatient(row){if(row)this.selectedPatient=row;},async addPatient(){if(!this.patient.name)return this.$message.warning('请填写患者姓名');this.saving=true;try{const p=await api.post('/patients',this.patient);this.patientDialog=false;this.selectedPatient=p;this.patientSearch=p.case_no;await this.loadPatients();this.$message.success('患者主档已建立');this.patient={name:'',gender:'女',birth_date:null,age:0,settle_type:'自费',id_card:'',address:'',phone:''};}catch{}finally{this.saving=false;}},async register(){if(!this.selectedPatient||!this.scheduleId)return this.$message.warning('请选择患者和排班医生');if(cents(this.received)<this.registrationFee)return this.$message.warning('实收金额不足');this.saving=true;try{const r=await api.post('/registrations',{patient_id:this.selectedPatient.id,schedule_id:this.scheduleId,book_requested:this.book,pay_method:this.payMethod,received_cents:cents(this.received),request_key:key()});this.$message.success('挂号和收费已完成');this.$emit('receipt',r.receipt);await this.loadSchedules();this.scheduleId='';}catch{}finally{this.saving=false;}},async loadEncounters(page){if(page)this.page=page;this.loading=true;try{this.encounters=await api.get('/encounters',{params:{q:this.search,page:this.page}});}catch{}finally{this.loading=false;}},async selectEncounter(row){if(!row)return;try{this.detail=await api.get(`/encounters/${row.id}`);this.selectedOrders=[];}catch{}},chargeable(o){return o.billing_status==='UNPAID'&&o.execution_status==='PENDING'&&o.kind!=='REG';},refundable(o){return o.kind!=='REG'&&o.billing_status==='PAID'&&(o.execution_status==='PENDING'||(o.kind==='DRUG'&&o.execution_status==='RETURNED'));},async charge(){this.saving=true;try{const r=await api.post('/charges',{encounter_id:this.detail.encounter.id,order_ids:this.selectedOrders.map(o=>o.id),pay_method:this.billMethod,received_cents:cents(this.billReceived),request_key:key()});this.$emit('receipt',r);this.$message.success('收款完成');await this.selectEncounter(this.detail.encounter);}catch{}finally{this.saving=false;}},async refund(order){const r=await reason(this,'项目退费');if(!r)return;try{await api.post(`/orders/${order.id}/refund`,{reason:r});this.$message.success('退款已记录');await this.selectEncounter(this.detail.encounter);}catch{}},async cancelRegistration(){const r=await reason(this,'未诊患者退号');if(!r)return;try{await api.post(`/encounters/${this.detail.encounter.id}/cancel`,{reason:r});this.$message.success('退号和挂号费退款已完成');await this.selectEncounter(this.detail.encounter);await this.loadEncounters();await this.loadSchedules();}catch{}},async openReceipt(id){try{this.$emit('receipt',await api.get(`/invoices/${id}`));}catch{}}}};
</script>
